import type { ContentResult } from '../types/intent'
import { safeUrl } from './safeUrl'

// No Contentstack schema change needed — the thumbnail is served by URL convention:
// an entry with url "/guides/rooftop-dinner-date-outfit" maps to
// /images/guides/rooftop-dinner-date-outfit.png. Generated by
// scripts/generate-cms-images.py — see that file for how the image is chosen per entry
// (an editorial photo prompt built from the entry's own title + summary, not a template).
// The slug is the last segment of a CMS-authored url, so it's untrusted like the rest of the
// entry — encodeURIComponent keeps it inside the one path segment the convention expects,
// mirroring host/guide.html's slugFromUrl/heroSrc handling of the same value.
function imageUrlFor(contentUrl: string): string {
  const slug = contentUrl.split('/').filter(Boolean).pop() ?? 'default'
  return `/images/guides/${encodeURIComponent(slug)}.png`
}

// Fallback gradient, shown behind the <img> — covers the moment before an image loads,
// and any entry that doesn't have a generated image yet (onError hides the broken <img>,
// leaving just this). Hashes the title to a stable index so the same guide always gets
// the same look.
const COVERS = [
  'linear-gradient(155deg, #F6D9A0 0%, #E8A85C 40%, #8B5A3C 78%, #3D2A24 100%)',
  'linear-gradient(155deg, #E8DCC8 0%, #C9A876 45%, #8A6642 78%, #5C4530 100%)',
  'linear-gradient(160deg, #A7C7D9 0%, #6E96AE 45%, #3E5E72 80%, #22384A 100%)',
  'linear-gradient(160deg, #D9B7C7 0%, #B37A96 45%, #7A4A63 80%, #402331 100%)',
  'linear-gradient(160deg, #C7D9B0 0%, #93B36E 45%, #5E7A42 80%, #2E3D1F 100%)',
]
function coverFor(seed: string): string {
  let hash = 0
  for (let i = 0; i < seed.length; i++) hash = (hash * 31 + seed.charCodeAt(i)) >>> 0
  return COVERS[hash % COVERS.length]
}

const TYPE_LABEL: Record<string, string> = {
  buying_guide: 'Buying Guide',
  how_to: 'How To',
  project_guide: 'Project Guide',
}

interface Props {
  content: ContentResult
  skin: string
}

export function CMSCardView({ content, skin }: Props) {
  return (
    // target="_top" — the Greeter runs inside an iframe, so a plain href would navigate
    // just that iframe, leaving the host page behind it frozen/blurred. ?skin=... —
    // content.url is a bare CMS path with no idea which skin the shopper is browsing;
    // without this the destination page defaults to skin=project (wrong accent color)
    // regardless of the actual site.
    <a className="g-cms-card" href={`${safeUrl(content.url)}?skin=${skin}`} target="_top">
      <span className="g-cms-card-cover" style={{ background: coverFor(content.title) }}>
        <img
          src={imageUrlFor(content.url)}
          alt=""
          onError={e => { e.currentTarget.style.display = 'none' }}
        />
      </span>
      <span className="g-cms-card-body">
        <span className="g-cms-card-title">{content.title}</span>
        <span className="g-cms-card-type">{TYPE_LABEL[content.contentType] ?? content.contentType}</span>
      </span>
    </a>
  )
}
